// One-use, local development probe. Only an app-private marker armed through run-as permits it.
if ("org.weltall.game.TEST_RECREATE_ACTIVITY".equals(newIntent.getAction())) {
    java.io.File marker = new java.io.File(getCacheDir(), "weltall-recreate-once");
    if (marker.isFile() && marker.delete()) {
        android.util.Log.i("WeltallLifecycleProbe", "Recreate requested activity=" + System.identityHashCode(this));
        getWindow().getDecorView().post(() -> recreate());
    }
}

